function validate([matrix]) {
  if (matrix.length < 1 || matrix.length > 1000) return 'matrix needs 1 to 1000 rows.';
  const n = matrix[0].length;
  if (n < 1 || n > 1000) return 'Each row needs 1 to 1000 cells.';
  for (const row of matrix) {
    if (row.length !== n) return 'Every row must have the same length.';
    if (!/^[.#A-Z]+$/.test(row)) return "Cells are '.', '#' or an uppercase letter.";
  }
  if (matrix[0][0] === '#') return 'The top-left cell cannot be a wall.';
  return null;
}

