function minMoves(matrix) {
  const rows = matrix.length;
  const cols = matrix[0].length;
  const portals = new Map();
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const cell = matrix[r][c];
      if (cell === '.' || cell === '#') continue;
      if (!portals.has(cell)) portals.set(cell, []);
      portals.get(cell).push([r, c]);
    }
  }

  const seen = Array.from({ length: rows }, () => new Array(cols).fill(false));
  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  seen[0][0] = true;
  let frontier = [[0, 0]];
  for (let moves = 0; frontier.length > 0; moves++) {
    for (let i = 0; i < frontier.length; i++) {
      const [r, c] = frontier[i];
      const letter = matrix[r][c];
      if (!portals.has(letter)) continue;
      for (const [pr, pc] of portals.get(letter)) {
        if (seen[pr][pc]) continue;
        seen[pr][pc] = true;
        frontier.push([pr, pc]);
      }
      portals.delete(letter);
    }
    const next = [];
    for (const [r, c] of frontier) {
      if (r === rows - 1 && c === cols - 1) return moves;
      for (const [dr, dc] of directions) {
        const nr = r + dr;
        const nc = c + dc;
        if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
        if (matrix[nr][nc] === '#' || seen[nr][nc]) continue;
        seen[nr][nc] = true;
        next.push([nr, nc]);
      }
    }
    frontier = next;
  }
  return -1;
}

