function minMoves(matrix) {
  // Dijkstra over states (row, column, set of letters already jumped with), following the rules
  // literally, with a linear scan for the closest unfinished state.
  const rows = matrix.length, cols = matrix[0].length;
  const letters = [...new Set(matrix.join('').replace(/[.#]/g, ''))];
  const key = (r, c, used) => `${r},${c},${used}`;
  const best = new Map([[key(0, 0, 0), 0]]);
  const done = new Set();
  const relax = (r, c, used, d) => {
    const k = key(r, c, used);
    if (!best.has(k) || d < best.get(k)) best.set(k, d);
  };
  for (;;) {
    let current = null, distance = Infinity;
    for (const [k, d] of best) if (!done.has(k) && d < distance) { current = k; distance = d; }
    if (current === null) return -1;
    done.add(current);
    const [r, c, used] = current.split(',').map(Number);
    if (r === rows - 1 && c === cols - 1) return distance;
    for (const [dr, dc] of [[0, 1], [1, 0], [0, -1], [-1, 0]]) {
      const x = r + dr, y = c + dc;
      if (x >= 0 && x < rows && y >= 0 && y < cols && matrix[x][y] !== '#') relax(x, y, used, distance + 1);
    }
    const bit = letters.indexOf(matrix[r][c]);
    if (bit >= 0 && (used & (1 << bit)) === 0)
      for (let x = 0; x < rows; x++)
        for (let y = 0; y < cols; y++)
          if ((x !== r || y !== c) && matrix[x][y] === matrix[r][c]) relax(x, y, used | (1 << bit), distance);
  }
}

