function generate(rand, size) {
  const large = size === 'large';
  const pick = list => list[Math.floor(rand() * list.length)];
  const letters = large ? 'ABCDEFGHIJKLMNOPQRSTUVWXYZ' : 'ABCD'.slice(0, 1 + Math.floor(rand() * 3));
  if (large && rand() < 0.4) {
    // A winding corridor: wall rows with one gap at alternating ends, plus a few portal pairs.
    const rows = 99, cols = 100;
    const grid = [];
    for (let r = 0; r < rows; r++) {
      if (r % 2 === 0) grid.push(Array(cols).fill('.'));
      else grid.push(Array.from({ length: cols }, (_, c) => (c === (r % 4 === 1 ? cols - 1 : 0) ? '.' : '#')));
    }
    const pairs = Math.floor(rand() * 6);
    for (let p = 0; p < pairs; p++)
      for (let k = 0; k < 2; k++) grid[2 * Math.floor(rand() * 50)][Math.floor(rand() * cols)] = letters[p];
    return [grid.map(row => row.join(''))];
  }
  const rows = large ? 60 + Math.floor(rand() * 41) : pick([1, 2, 3, 3, 4, 4, 5]);
  const cols = large ? 60 + Math.floor(rand() * 41) : pick([1, 2, 3, 4, 4, 5, 5]);
  const wall = rand() * 0.4;
  const portal = large ? 0.01 + rand() * 0.05 : rand() * 0.4;
  const grid = [];
  for (let r = 0; r < rows; r++) {
    let row = '';
    for (let c = 0; c < cols; c++) {
      const x = rand();
      if (x < wall) row += r + c === 0 ? '.' : '#';
      else if (x < wall + portal) row += pick(letters);
      else row += '.';
    }
    grid.push(row);
  }
  return [grid];
}
